-- Retires the R5 raw UNIQUE indexes whose text columns carry dbmigrate.ci_ai (ICU primary, nondeterministic).
-- They can reject values MySQL accepts: ICU folds ss/sharp-s and ae/ligature and treats combining marks and
-- ignorables differently from MySQL unicode_ci/general_ci weights (general_ci: sharp-s = s).
-- Every dropped index has an ixwk__ twin (exact MySQL weight key) and an ixpad__ twin (flag-off ON CONFLICT).
-- Names come from full-pg-plan/plan.sql (R5 import plan); query 1 confirms them on scratch first.
-- Ends with ROLLBACK: the coordinator replaces it with COMMIT on the disposable scratch only.

-- 0 every ixwk twin present, valid and unique (expect 134) - or run PADQA_WK=1 pad-gate-check
SELECT COUNT(*) AS ixwk_valid FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname LIKE 'ixwk%' AND i.indisvalid AND i.indisunique;
